#!/bin/sh
# Writes ref_convert.c: the converter of doomgeneric_wayland.c as it was
# before dg_present existed, extracted from git, with just enough around it
# to call it. The table construction is copied from applyResize of the same
# commit.
#
#   gen_ref_convert.sh [commit] > ref_convert.c
set -e
COMMIT=${1:-a1ceef6}
SRC=$(git show "$COMMIT:doomgeneric/doomgeneric_wayland.c")
cat <<'HEAD'
/* Generated by gen_ref_convert.sh from the Wayland back end before dg_present. */
#include <stdint.h>
#include <string.h>
#include <stdlib.h>

#define WL_SHM_FORMAT_RGB565 0x36314752
#define WL_SHM_FORMAT_XRGB8888 1
#define SCREENWIDTH 320
#define SCREENHEIGHT 200
typedef uint8_t pixel_t;
struct buffer { void *data; };

static const pixel_t *DG_ScreenBuffer;
static int s_Width, s_Height, s_Bpp, s_PicX, s_PicY, s_PicWidth, s_PicHeight;
static int *s_XMap, *s_YMap;
static uint32_t s_Format;
static uint16_t s_Pal565[256];
static uint32_t s_Pal8888[256];

HEAD
printf '%s\n' "$SRC" | awk '/^static void convertFrame/ {on=1} on {print} on && /^}/ {exit}'
cat <<'TAIL'

void ref_setup(int w, int h, int px, int py, int pw, int ph, int bpp)
{
	int i;

	s_Width = w;
	s_Height = h;
	s_PicX = px;
	s_PicY = py;
	s_PicWidth = pw;
	s_PicHeight = ph;
	s_Bpp = bpp;
	s_Format = bpp == 2 ? WL_SHM_FORMAT_RGB565 : WL_SHM_FORMAT_XRGB8888;
	s_XMap = realloc(s_XMap, s_PicWidth * sizeof(*s_XMap));
	s_YMap = realloc(s_YMap, s_PicHeight * sizeof(*s_YMap));
	for (i = 0; i < s_PicWidth; i++)
	{
		s_XMap[i] = ((2 * i + 1) * SCREENWIDTH) / (2 * s_PicWidth);
	}
	for (i = 0; i < s_PicHeight; i++)
	{
		s_YMap[i] = ((2 * i + 1) * SCREENHEIGHT) / (2 * s_PicHeight) * SCREENWIDTH;
	}
}

void ref_convert(void *data, const uint8_t *src, const uint16_t *p565,
                 const uint32_t *p8888)
{
	struct buffer b = { data };

	DG_ScreenBuffer = src;
	memcpy(s_Pal565, p565, sizeof(s_Pal565));
	memcpy(s_Pal8888, p8888, sizeof(s_Pal8888));
	convertFrame(&b);
}
TAIL
